# Try: compare each cell to its left neighbor, output 0 if different, original value if same
input_grid = [5, 5, 5, 4, 4, 9, 7, 4, 7, 4, 7, 4, 9, 4, 4, 4]
result = []
if input_grid:
    result.append(input_grid[0])  # First cell always kept
    for i in range(1, len(input_grid)):
        if input_grid[i] == input_grid[i-1]:
            result.append(0)  # Same as previous
        else:
            result.append(input_grid[i])  # New value

print(f"Submission: {result}")

